/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_QUOTE_HEADER
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_QUOTE   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : SCD2
   feeders     : 2 emitted of 2 (one per source view AND run)
   runs        : 2 -- opus_health_legacy_v4, opus_health_v2
   payload     : 10 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_QUOTE_HK
   hashdiff    : SAT_QUOTE_HEADER_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   BESPOKE LAYER dual_feed_satellite_loader (s6.5): BOTH runs write this satellite.
   The standard satellite layer unions feeders that are disjoint by construction,
   which is the assumption two independent writers break.
*/

with feeders as (
    select
        md5(upper('HUB_QUOTE|' || (HUB_QUOTE_BK__QUOTE_SUB_NO))) as HUB_QUOTE_HK
        , PRIORITY as QUOTE_PRIORITY
        , RESOLUTION_DATE as QUOTE_RESOLUTION_DATE
        , SUBJECT as QUOTE_SUBJECT
        , DESCRIPTION as QUOTE_DESCRIPTION
        , QUOTE_SUB_STATUS as QUOTE_SUB_STATUS
        , QUOTE_SUB_STATUS_DESC as QUOTE_SUB_STATUS_DESCRIPTION
        , DATA_INFORMATION as QUOTE_DATA_INFORMATION
        , LAST_QUOTE_SUB_DATE as LAST_QUOTE_SUBMISSION_DATE
        , cast(null as varchar) as QUOTE_BUSINESS_TYPE
        , cast(null as varchar) as QUOTE_COPY_REFERENCE
        , 'BJAZ_GRP_HLT_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_grp_hlt_dtls') }}
    where (nullif(trim(QUOTE_SUB_NO),'')) is not null
    union all
    select
        md5(upper('HUB_QUOTE|' || (HUB_QUOTE_BK__QUOTATION_NO))) as HUB_QUOTE_HK
        , cast(null as varchar) as QUOTE_PRIORITY
        , cast(null as varchar) as QUOTE_RESOLUTION_DATE
        , cast(null as varchar) as QUOTE_SUBJECT
        , cast(null as varchar) as QUOTE_DESCRIPTION
        , cast(null as varchar) as QUOTE_SUB_STATUS
        , cast(null as varchar) as QUOTE_SUB_STATUS_DESCRIPTION
        , cast(null as varchar) as QUOTE_DATA_INFORMATION
        , cast(null as varchar) as LAST_QUOTE_SUBMISSION_DATE
        , QUOTATION_TYPE as QUOTE_BUSINESS_TYPE
        , QUOTE_COPY as QUOTE_COPY_REFERENCE
        , 'BJAZ_ENROLL_POL_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_enroll_pol_dtls') }}
    where (nullif(trim(QUOTATION_NO),'')) is not null
),

resolved as (
    select
        HUB_QUOTE_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then QUOTE_PRIORITY end) as QUOTE_PRIORITY,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then QUOTE_RESOLUTION_DATE end) as QUOTE_RESOLUTION_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then QUOTE_SUBJECT end) as QUOTE_SUBJECT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then QUOTE_DESCRIPTION end) as QUOTE_DESCRIPTION,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then QUOTE_SUB_STATUS end) as QUOTE_SUB_STATUS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then QUOTE_SUB_STATUS_DESCRIPTION end) as QUOTE_SUB_STATUS_DESCRIPTION,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then QUOTE_DATA_INFORMATION end) as QUOTE_DATA_INFORMATION,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then LAST_QUOTE_SUBMISSION_DATE end) as LAST_QUOTE_SUBMISSION_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then QUOTE_BUSINESS_TYPE end) as QUOTE_BUSINESS_TYPE,
        max(case when SOURCE_RUN = 'opus_health_v2' then QUOTE_COPY_REFERENCE end) as QUOTE_COPY_REFERENCE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_QUOTE_HK
),

hashed as (
    select
        *,
        case when QUOTE_PRIORITY is not null or QUOTE_RESOLUTION_DATE is not null or QUOTE_SUBJECT is not null or QUOTE_DESCRIPTION is not null or QUOTE_SUB_STATUS is not null or QUOTE_SUB_STATUS_DESCRIPTION is not null or QUOTE_DATA_INFORMATION is not null or LAST_QUOTE_SUBMISSION_DATE is not null or QUOTE_BUSINESS_TYPE is not null or QUOTE_COPY_REFERENCE is not null
                     then md5(upper(coalesce(cast(QUOTE_PRIORITY as varchar), '') || '|' || coalesce(cast(QUOTE_RESOLUTION_DATE as varchar), '') || '|' || coalesce(cast(QUOTE_SUBJECT as varchar), '') || '|' || coalesce(cast(QUOTE_DESCRIPTION as varchar), '') || '|' || coalesce(cast(QUOTE_SUB_STATUS as varchar), '') || '|' || coalesce(cast(QUOTE_SUB_STATUS_DESCRIPTION as varchar), '') || '|' || coalesce(cast(QUOTE_DATA_INFORMATION as varchar), '') || '|' || coalesce(cast(LAST_QUOTE_SUBMISSION_DATE as varchar), '') || '|' || coalesce(cast(QUOTE_BUSINESS_TYPE as varchar), '') || '|' || coalesce(cast(QUOTE_COPY_REFERENCE as varchar), '')))
                end as SAT_QUOTE_HEADER_HASHDIFF
    from resolved
)

select * from hashed
where HUB_QUOTE_HK is not null
  and SAT_QUOTE_HEADER_HASHDIFF is not null
